    # Initialize DP table
    dp = [[-float('inf')] * (k + 1) for _ in range(n + 1)]
    dp[0][k] = 0

    # Process each castle
    for i in range(1, n + 1):
        a, b, c = castles[i - 1]
        for j in range(k + 1):
            if dp[i - 1][j] == -float('inf'):
                continue
            # Option 1: Capture the castle
            if j >= a:
                dp[i][j - a] = max(dp[i][j - a], dp[i - 1][j] + c)
            # Option 2: Hire warriors and then capture the castle
            if j + b >= a:
                dp[i][j + b - a] = max(dp[i][j + b - a], dp[i - 1][j] + c)

    # Check if all castles can be captured
    if dp[n][0] == -float('inf'):
        print(-1)
        return

    # Calculate the maximum score by considering all possible ways to defend the castles
    max_score = 0
    for i in range(n + 1):
        for j in range(k + 1):
            if dp[i][j] != -float('inf'):
                max_score = max(max_score, dp[i][j])

    print(max_score)

